def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            if metadata:
                from neo4j import TransactionError
                try:
                    result = tx.with_metadata(metadata).run(result)
                except TransactionError:
                    print("Transaction error:", result.error_code())
                    return
            if timeout:
                from neo4j importTimeout
                try:
                    result = tx.with_timeout(timeout).run(result)
                except Timeout:
                    print("Timeout error:", result.error_code)
                    return
            return result
    return wrapper
