def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if isinstance(cmd, str):
        cmd = [cmd]
    # If there is a #! at the beginning of the command, strip it
    if cmd[0].startswith("#!"):
        cmd[0] = cmd[0][2:]
    # If the command starts with "\\?\", change it to "/"
    if cmd[0].startswith("\\?\""):
        cmd[0] = cmd[0].replace("\\?\", "/")
    # If the first element is "py" or "python", change it to the absolute path of python
    if cmd[0] in ("py", "python"):
        cmd[0] = sys.executable
