        @functools.wraps(func)
        def cached_func(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if settings.typed else (args,)
            lastTTL = ()

            while True:
                now = settings.timer()
                lastTTL = lastTTL + (now,)
                if len(lastTTL) >= settings.ttl:
                    # calculate how old the oldest entry is
                    oldest = now - lastTTL[0]
                    if oldest > settings.ttl:
