def lfu_cache(func):
    _cache: Dict[Any, Any] = {}
    _freq: DefaultDict[Any, int] = defaultdict(int)
    _freq_items: Set[Any] = set()
    _curr_size = 0
    _maxsize = maxsize if maxsize is not None else 128
    _typed = typed if typed is not None else False

    def _get_freq(key):
        if _typed:
            return _freq[type(key)]
        else:
            return sum(freq[k] for k in _freq_items)

    def _set_freq(key):
        nonlocal _curr_size
        if _typed:
            _freq[type(key)] += 1
        else:
            _freq[key] += 1
        _curr_size += 1

    def _remove_item(key):
        del _cache[key]
        if _typed:
            _freq.pop(type(key))
        else:
            for k in _freq_items:
                if k == key:
                    break
            _freq_items.remove(k)

    def _memoize(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args[0] if not kwargs else tuple(kwargs.values())
            if key in _cache:
                _set_freq(key)
                return _cache[key]
            else:
                if _curr_size >= _maxsize:
                    _remove_item(key)
                result = func(*args, **kwargs)
                _cache[key] = result
                _set_freq(key)
                return result

        return wrapper

    return _memoize(func)
