def format_sql(sql, params):
    # convert the SQL query to use out-style parameters
    # if the parameters are a dictionary, then use named out-style parameters
    # if the parameters are a sequence, then use ordinal out-style parameters
    if isinstance(params, dict):
        for param, value in params.items():
            if isinstance(param, str):
                sql = sql.replace(":" + param, value)
            elif isinstance(param, int):
                sql = sql.replace(":" + str(param), value)
    elif isinstance(params, sequence):
        for index, value in enumerate(params):
            sql = sql.replace(":", value)
    return sql, params
