def pretty(self, indent=0, debug=False):
    result = ''
    if self is None:
        result += 'None '
    elif isinstance(self, str):
        result += self
    elif isinstance(self, list):
        if debug:
            result += f'[{", ".join(map(pretty, self))}']
        else:
            result += f'[{", ".join(map(str, self))}]'
    elif isinstance(self, tuple):
        if debug:
            result += f'({", ".join(map(pretty, self))})'
        else:
            result += f'({", ".join(map(str, self))})'
    elif isinstance(self, dict):
        result += '{'
        for key, value in self.items():
            result += f'{pretty(key)}: {pretty(value)}'
        result += '}'
    else:
        result += str(self)
