CREATE FUNCTION _fromutc(dt datetime)
RETURNS datetime
BEGIN
  /*
   * Since this is the one time that we *know* we have an unambiguous datetime object,
   * we take this opportunity to determine whether the datetime is ambiguous and in a "fold" state.
   */
  IF ISAMBIGUOUS(dt) = 1 THEN
    RETURN dt;
  ELSE
    RETURN dt + INTERVAL @@time_zone.effective_go_offset() MINUTE;
  END IF;
END;
