        self.days = int(self.days)
        if self.days < 0:
            self.days += 1
        elif self.days > 0:
            self.days -= 1
    if self.seconds is not None:
        self.hours += int((self.seconds % 3600) // 3600)
        self.minutes += int((self.seconds % 60) // 60)
        self.seconds = int(self.seconds % 60)
    if self.microseconds is not None:
        self.seconds += self.microseconds / 1000000
        self.microseconds = int(self.microseconds % 1000000)
    if self.hours > 0:
