        temp_repo_dir = Path(tmp_path) / f"repo-{uuid.uuid4()}"
        unzip_process = subprocess.run(["jar", "-x", archive_path, "-d", str(temp_repo_dir)])
        if unzip_process.returncode == 0:
            return str(temp_repo_dir)
        else:
            raise RuntimeError(f"Failed to extract jar file: {archive_path}")
    else:
        raise ValueError(f"Unsupported archive format for {archive_path}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.isfile(archive_path):
        raise ValueError("Please provide a valid file path")
    if filename and not os.path.isfile(os.path.join(tmp_path, filename)):
        raise ValueError("File does not exist in the tmp directory")
    proc = subprocess.Popen(["tar", "-xvzf", archive_path], cwd=tmp_path)
    proc.wait()
    src_path = os.path.splitext(os.path.basename(archive_path))[0]
    if filename:
        src_path = os.path.join(tmp_path, src_path, filename)
    return "file:" + os.path.abspath(src_path)

