    max_val = args.get("max_val")
    value = args.get("value")
    if min_val is not None and value is not None and value < min_val:
        raise ValueError("Value must be greater than or equal to minimum value")
    if max_val is not None and value is not None and value > max_val:
        raise ValueError("Value must be less than or equal to maximum value")
