def get_nested_custom_and_control_args(args):
    control_args = dict()
    nested_args = dict()
    custom_args = dict()

    for arg in args:
        if arg[0][0] == '-' and arg[0][1].islower():
            control_args[arg] = args.pop(0)
        elif arg[0][0] == ':' and arg[0][1].isupper():
            custom_args[arg] = args.pop(0)
        else:
            nested_args[arg] = args.pop(0)

    return control_args, nested_args, custom_args
