def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    cmd = "ansible-playbook -i {} --vault-id {}".format(
        ir_workspace.get_workspace_vault_file(),
        ir_plugin.get_plugin_vault_file()
    )
    if verbose:
        cmd += " --verbose"
    if extra_vars:
        cmd += " --extra-vars", extra_vars.strip()
    if ansible_args:
        cmd += " " + ansible_args.strip()
    cmd += " " + playbook_path.strip()
    return cmd
